"""Token issuance time encoding."""
from datetime import datetime, timezone

def serialize_issuance_time(dt: datetime) -> str:
    if dt.tzinfo is not None and dt.utcoffset() == timezone.utc.utcoffset(None):
        # UTC case: format as Z suffix with milliseconds
        return dt.strftime('%Y-%m-%dT%H:%M:%S.000Z')
    else:
        # Non-UTC case: standard isoformat
        return dt.isoformat()

def compute_token_expiry_epoch(dt: datetime, lifetime_seconds: int = 3600) -> int:
    return int(dt.timestamp()) + lifetime_seconds
